// Synthetic demo source: procedurally animated two-hand poses generated by
// forward kinematics on the anatomical template. It bypasses the neural
// models (clearly labelled in the UI) so the rig, aura, prediction and HUD can
// be inspected without a camera. Gestures are still classified by the real
// classifier from the generated keypoints.

import { NUM_KP, PARENT, FINGERS, BONE_LENGTH, template, sub, norm, cross, dot, add, scale } from '../core/handModel.js';
import { classifyGesture } from '../core/gestures.js';

const POSES = {
  open: { thumb: [0.05, 0.05, 0.05], f: [[0.05, 0.05, 0.05], [0.05, 0.05, 0.05], [0.05, 0.05, 0.05], [0.05, 0.05, 0.05]] },
  fist: { thumb: [0.5, 0.7, 0.9], f: [[1.45, 1.7, 1.0], [1.5, 1.75, 1.05], [1.5, 1.75, 1.05], [1.45, 1.7, 1.0]] },
  point: { thumb: [0.5, 0.7, 0.9], f: [[0.0, 0.05, 0.05], [1.5, 1.75, 1.05], [1.5, 1.75, 1.05], [1.45, 1.7, 1.0]] },
  victory: { thumb: [0.5, 0.7, 0.9], f: [[0.0, 0.05, 0.05], [0.0, 0.05, 0.05], [1.5, 1.75, 1.05], [1.45, 1.7, 1.0]] },
  rock: { thumb: [0.4, 0.6, 0.8], f: [[0.0, 0.05, 0.05], [1.5, 1.75, 1.05], [1.5, 1.75, 1.05], [0.0, 0.05, 0.05]] },
  claw: { thumb: [0.25, 0.4, 0.5], f: [[0.4, 1.1, 0.8], [0.4, 1.1, 0.8], [0.4, 1.1, 0.8], [0.4, 1.1, 0.8]] },
};
const SEQ = ['open', 'claw', 'fist', 'point', 'victory', 'rock', 'open'];

function rotAxis(v, axis, ang) {
  const a = norm(axis), c = Math.cos(ang), s = Math.sin(ang);
  const d = dot(a, v), x = cross(a, v);
  return add(add(scale(v, c), scale(x, s)), scale(a, d * (1 - c)));
}

function lerpPose(a, b, t) {
  const L = (x, y) => x.map((v, i) => v + (y[i] - v) * t);
  return { thumb: L(a.thumb, b.thumb), f: a.f.map((ff, i) => L(ff, b.f[i])) };
}

// Hand-frame keypoints for a pose.
export function poseKeypoints(handedness, pose) {
  const T = template(handedness);
  const mx = handedness === 'left' ? -1 : 1;
  const P = T.map((v) => [...v]);
  FINGERS.forEach((fg, fi) => {
    const ang = fi === 0 ? pose.thumb : pose.f[fi - 1];
    const base = fg.chain[1];
    const d0 = norm(sub(T[fg.chain[2]], T[base]));
    const axis = fi === 0 ? cross(d0, norm([-0.6 * mx, 0, 1])) : cross(d0, [0, 0, 1]);
    let phi = 0;
    for (let k = 2; k <= 4; k++) {
      const j = fg.chain[k];
      phi += ang[k - 2];
      const d = rotAxis(d0, axis, phi);
      P[j] = add(P[PARENT[j]], scale(d, BONE_LENGTH[j]));
    }
  });
  return P;
}

export class SyntheticSource {
  constructor() {
    this.W = 1280; this.H = 720;
    this.t0 = performance.now();
    this.prev = {};
  }

  frame(tMs, hfovDeg) {
    const t = (tMs - this.t0) / 1000;
    const f = (Math.max(this.W, this.H) / 2) / Math.tan((hfovDeg * Math.PI) / 360);
    const cam = { f, cx: this.W / 2, cy: this.H / 2 };
    const hands = [];
    for (const [i, side] of ['left', 'right'].entries()) {
      const ph = t * 0.45 + i * 1.7;
      const seg = ((ph % SEQ.length) + SEQ.length) % SEQ.length;
      const k = Math.floor(seg), u = seg - k;
      const e = u < 0.6 ? 0 : (u - 0.6) / 0.4;
      const pose = lerpPose(POSES[SEQ[k]], POSES[SEQ[(k + 1) % SEQ.length]], e * e * (3 - 2 * e));
      const local = poseKeypoints(side, pose);
      // Palm towards the camera, fingers up, gentle sway.
      const yaw = Math.sin(t * 0.7 + i) * 0.5, pitch = 0.25 + Math.sin(t * 0.5 + i * 2) * 0.25, roll = Math.sin(t * 0.6 + i) * 0.35;
      const pos = [(side === 'left' ? 0.11 : -0.11) + Math.sin(t * 0.8 + i) * 0.04, 0.06 + Math.cos(t * 0.9 + i) * 0.03, 0.5 + Math.sin(t * 0.4 + i) * 0.06];
      const kp3d = new Float32Array(NUM_KP * 3), kp2d = new Float32Array(NUM_KP * 2);
      local.forEach((p, j) => {
        // base orientation: hand Y → -y (up), hand Z → -z (towards camera)
        let q = [p[0], -p[1], -p[2]];
        q = rotAxis(q, [0, 0, 1], roll);
        q = rotAxis(q, [0, 1, 0], yaw);
        q = rotAxis(q, [1, 0, 0], pitch);
        const w = add(q, pos);
        kp3d.set(w, 3 * j);
        kp2d[2 * j] = cam.f * w[0] / w[2] + cam.cx;
        kp2d[2 * j + 1] = cam.f * w[1] / w[2] + cam.cy;
      });
      const prev = this.prev[side];
      const vel2d = new Float32Array(NUM_KP * 2), vel3d = new Float32Array(NUM_KP * 3);
      if (prev && t > prev.t) {
        const dt = t - prev.t;
        for (let j = 0; j < NUM_KP * 2; j++) vel2d[j] = (kp2d[j] - prev.kp2d[j]) / dt;
        for (let j = 0; j < NUM_KP * 3; j++) vel3d[j] = (kp3d[j] - prev.kp3d[j]) / dt;
      }
      this.prev[side] = { t, kp2d, kp3d };
      const g = classifyGesture(kp3d, kp2d);
      hands.push({
        id: i + 1, handedness: side, facing: 'palm', state: 'tracking', score: 0.9,
        kp2d, vel2d, kpRaw: kp2d, kpScores: new Float32Array(NUM_KP).fill(0.9), kp3d, vel3d,
        depth: pos[2], gesture: g.name, gestureScore: g.score, noisePx: 0,
      });
    }
    return { W: this.W, H: this.H, cam, hands };
  }
}
